static void draw_goo(void){if(!g.fx)return;nquad=0;SDL_Texture*batch=gooTexture;for(int i=0;i<GOO_CAPACITY;i++){GooDrop*p=goo+i;if(p->life<=0)continue;SDL_Texture*t=p->blood?bloodTexture:gooTexture;if(t!=batch){flush(batch);batch=t;}const float*u=p->blood?bloodUV[p->cell]:gooUV[p->cell];float fade=1-p->age/p->life,expand=p->cell==2?1+p->age*.3f:1,w=p->size*2*expand,h=w*u[3]*1024/(u[2]*1536),alpha=fminf(1,fade*3)*(p->cell==0?.30f:p->cell==2?.22f:.90f);int at=nquad;quad((p->x-w/2)*3,(p->y-h/2)*3,w*3,h*3,(SDL_FColor){1,1,1,alpha},u[0],u[1],u[2],u[3]);if(nquad==at)break;float a=p->angle*PI/180,c=cosf(a),s=sinf(a),cx=p->x*3,cy=p->y*3;for(int v=at*4;v<at*4+4;v++){float x=vertices[v].position.x-cx,y=vertices[v].position.y-cy;vertices[v].position.x=cx+x*c-y*s;vertices[v].position.y=cy+x*s+y*c;}unwarp_quad(cx,cy);}flush(batch);}
